'use client';

import { useState } from 'react';
import { toast } from 'sonner';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Progress } from '@/components/ui/progress';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow
} from '@/components/ui/table';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

const alunos = [
  { nome: 'Ana Silva', ano: '9.º', turma: 'Matemática', pago: true },
  { nome: 'João Costa', ano: '12.º', turma: 'Física', pago: false },
  { nome: 'Marta Lopes', ano: '7.º', turma: 'Inglês', pago: true },
  { nome: 'Rui Pereira', ano: '11.º', turma: 'Matemática', pago: false }
];

const kpis = [
  { label: 'Alunos ativos', value: '128' },
  { label: 'Receita do mês', value: '9 420 €' },
  { label: 'Pagamentos em atraso', value: '7' },
  { label: 'Assiduidade', value: '94%' }
];

export default function Page() {
  const [q, setQ] = useState('');
  const lista = alunos.filter((a) => a.nome.toLowerCase().includes(q.toLowerCase()));

  return (
    <main className='mx-auto max-w-5xl space-y-6 p-6'>
      <div className='flex items-center justify-between'>
        <div>
          <h1 className='text-2xl font-bold'>Centro de Estudo</h1>
          <p className='text-muted-foreground text-sm'>Demo dos componentes</p>
        </div>
        <Button onClick={() => toast.success('Aluno criado (mock)')}>Novo aluno</Button>
      </div>

      <div className='grid grid-cols-2 gap-4 md:grid-cols-4'>
        {kpis.map((k) => (
          <Card key={k.label}>
            <CardHeader>
              <CardDescription>{k.label}</CardDescription>
              <CardTitle className='text-2xl'>{k.value}</CardTitle>
            </CardHeader>
          </Card>
        ))}
      </div>

      <Tabs defaultValue='alunos'>
        <TabsList>
          <TabsTrigger value='alunos'>Alunos</TabsTrigger>
          <TabsTrigger value='turmas'>Turmas</TabsTrigger>
        </TabsList>

        <TabsContent value='alunos' className='space-y-4'>
          <Input placeholder='Pesquisar aluno…' value={q} onChange={(e) => setQ(e.target.value)} />
          <Card>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Aluno</TableHead>
                    <TableHead>Ano</TableHead>
                    <TableHead>Turma</TableHead>
                    <TableHead>Mensalidade</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {lista.map((a) => (
                    <TableRow key={a.nome}>
                      <TableCell className='flex items-center gap-2'>
                        <Avatar>
                          <AvatarFallback>{a.nome.split(' ').map((n) => n[0]).join('')}</AvatarFallback>
                        </Avatar>
                        {a.nome}
                      </TableCell>
                      <TableCell>{a.ano}</TableCell>
                      <TableCell>{a.turma}</TableCell>
                      <TableCell>
                        <Badge variant={a.pago ? 'secondary' : 'destructive'}>
                          {a.pago ? 'Pago' : 'Em atraso'}
                        </Badge>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value='turmas' className='grid gap-4 md:grid-cols-3'>
          {[
            ['Matemática', 80],
            ['Física', 45],
            ['Inglês', 100]
          ].map(([nome, ocup]) => (
            <Card key={nome}>
              <CardHeader>
                <CardTitle>{nome}</CardTitle>
                <CardDescription>Ocupação {ocup}%</CardDescription>
              </CardHeader>
              <CardContent>
                <Progress value={Number(ocup)} />
              </CardContent>
            </Card>
          ))}
        </TabsContent>
      </Tabs>
    </main>
  );
}
